create table memory_background_learning_requests ( request_id text primary key , operation_key text not null , board text not null , stage text not null , entity_uri text , source_revision text , attempt integer not null check ( attempt >= 1 ) , provider_id text , model text , status text not null check ( status in ( 'started' , 'completed' , 'failed' , 'exhausted' , 'cancelled' ) ) , started_at text not null , started_at_ms integer not null , completed_at text , completed_at_ms integer , duration_ms integer check ( duration_ms is null or duration_ms >= 0 ) , retry_at_ms integer , error_code text , error_message text , usage_json text check ( usage_json is null or json_valid ( usage_json ) ) , metadata_json text not null default '{}' check ( json_valid ( metadata_json ) ) , session_id text ) strict;

-- table: memory_catalog_state
create table memory_catalog_state ( catalog text primary key , revision integer not null check ( revision >= 0 ) );

-- table: memory_episodes
create table memory_episodes ( id text primary key , uri text not null unique , session_id text not null , request_id text not null , status text not null , raw_user_text text not null , standalone_request text not null , context_basis text not null , topic text not null , assistant_text text not null , started_at text not null , completed_at text not null , updated_at text not null , started_at_ms integer not null , completed_at_ms integer not null , updated_at_ms integer not null , time_zone text not null , local_date text not null , local_hour text not null , metadata_json text not null , unique ( session_id , request_id ) );

-- table: memory_knowledge_scores
create table memory_knowledge_scores ( node_id text primary key ) strict;

-- table: memory_recall_receipts
create table memory_recall_receipts ( session_id text not null , request_id text not null , task_id text not null , node_id text not null , revision text not null , summary text not null , delivery text not null check ( delivery in ( 'snapshot' , 'task' , 'explicit' ) ) , delivered integer not null default 0 check ( delivered in ( 0 , 1 ) ) , primary key ( session_id , request_id , node_id , revision , delivery ) , foreign key ( session_id , request_id ) references memory_task_requests ( session_id , request_id ) on delete cascade ) strict;

-- table: memory_score_sync
create table memory_score_sync ( node_id text primary key references memory_knowledge_scores ( node_id ) on delete cascade , revision text not null ) strict;

-- table: memory_sources
create table memory_sources ( id text primary key , uri text not null unique , episode_id text not null , episode_uri text not null , session_id text not null , request_id text not null , source_kind text not null , role text not null , text_content text , summary text , conversation_entry_id text not null , evidence_uri text not null , artifact_uri text not null , tool_name text not null , created_at text not null , updated_at text not null , created_at_ms integer not null , updated_at_ms integer not null , time_zone text not null , local_date text not null , local_hour text not null , metadata_json text not null , foreign key ( episode_id ) references memory_episodes ( id ) on delete cascade );

-- table: memory_task_completions
create table memory_task_completions ( session_id text not null , request_id text not null , completed_at text not null , primary key ( session_id , request_id ) , foreign key ( session_id , request_id ) references memory_task_requests ( session_id , request_id ) on delete cascade ) strict;

-- table: memory_task_requests
create table memory_task_requests ( session_id text not null , request_id text not null , task_id text not null , subject_id text not null , actor_kind text not null check ( actor_kind in ( 'user' , 'agent' , 'unknown' ) ) , started_at text not null , primary key ( session_id , request_id ) ) strict;

-- table: memory_utility_settlements
create table memory_utility_settlements ( session_id text not null , request_id text not null , task_id text not null , node_id text not null , outcome text not null check ( outcome in ( 'helpful' , 'unhelpful' , 'unused' , 'uncertain' ) ) , reason text not null check ( length ( trim ( reason ) ) > 0 ) , contract_version integer not null check ( contract_version > 0 ) , primary key ( session_id , request_id , node_id ) , foreign key ( session_id , request_id ) references memory_task_requests ( session_id , request_id ) on delete cascade ) strict;

-- table: pi_compaction_candidates
create table pi_compaction_candidates ( candidate_id text primary key , session_id text not null , branch_epoch text , snapshot_leaf_id text not null , created_at text not null , candidate_json text not null );

